INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES ('95', '15', '3', '3', 'calculation', '14', '区域 \(\Omega:x^2+y^2+2z^2\le x+y+2z\)，密度为 \(x^2+y^2+z^2\)。求质量
\[M=\iiint_\Omega(x^2+y^2+z^2)\,\mathrm dx\,\mathrm dy\,\mathrm dz.\]', '\(M=5\pi/6\)。', '令 \(u=x-1/2,v=y-1/2,w=2(z-1/2)\)，区域化为单位球，Jacobi 行列式为 \(1/2\)。奇函数项积分为零，利用球域轮换对称性和球坐标积分，得到 \(M=5\pi/6\)。', '2016 年第八届全国大学生数学竞赛初赛（非数学类） 区域 ( :x 2+y 2+2z 2 x+y+2z )，密度为 (x 2+y 2+z 2 )。求质量 [M= (x 2+y 2+z 2) , dx , dy , dz. ] (M=5 /6 )。 令 (u=x-1/2,v=y-1/2,w=2(z-1/2) )，区域化为单位球，Jacobi 行列式为 (1/2 )。奇函数项积分为零，利用球域轮换对称性和球坐标积分，得到 (M=5 /6 )。', '1', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES ('96', '15', '4', '4', 'proof', '14', '设 \(f\in C^1[0,1]\)，\(f(0)=0,f(1)=1\)。证明
\[\lim_{n\to\infty}n\left[\int_0^1f(x)\,\mathrm dx-\frac1n\sum_{k=1}^nf(k/n)\right]=-\frac12.\]', '极限为 \(-1/2\)。', '把积分按 \(n\) 等分并与右端点 Riemann 和逐段相减，用中值定理写成 \(-\frac1{2n}\sum f''(\eta_k)/n\)。其极限为 \(-\frac12\int_0^1f''(x)\,\mathrm dx=-1/2\)。', '2016 年第八届全国大学生数学竞赛初赛（非数学类） 设 (f C 1[0,1] )， (f(0)=0,f(1)=1 )。证明 [ n n [ 0 1f(x) , dx- 1n k=1 nf(k/n) ]=- 12. ] 极限为 (-1/2 )。 把积分按 (n ) 等分并与右端点 Riemann 和逐段相减，用中值定理写成 (- 1 2n f''( k)/n )。其极限为 (- 12 0 1f''(x) , dx=-1/2 )。', '1', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES ('97', '15', '5', '5', 'proof', '14', '设 \(f\) 在 \([0,1]\) 上连续，\(I=\int_0^1f(x)\,\mathrm dx\ne0\)。证明在 \((0,1)\) 内存在不同两点 \(x_1,x_2\)，使
\[\frac1{f(x_1)}+\frac1{f(x_2)}=\frac2I.\]', '所述两点存在。', '令 \(F(x)=I^{-1}\int_0^xf(t)\,\mathrm dt\)。由介值定理取 \(\xi\) 使 \(F(\xi)=1/2\)。在 \([0,\xi]\)、\([\xi,1]\) 分别用 Lagrange 中值定理，所得两点分居两个区间，代数整理即得结论。', '2016 年第八届全国大学生数学竞赛初赛（非数学类） 设 (f ) 在 ([0,1] ) 上连续， (I= 0 1f(x) , dx 0 )。证明在 ((0,1) ) 内存在不同两点 (x 1,x 2 )，使 [ 1 f(x 1) + 1 f(x 2) = 2I. ] 所述两点存在。 令 (F(x)=I -1 0 xf(t) , dt )。由介值定理取 ( ) 使 (F( )=1/2 )。在 ([0, ] )、 ([ ,1] ) 分别用 Lagrange 中值定理，所得两点分居两个区间，代数整理即得结论。', '1', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES ('98', '15', '6', '6', 'proof', '14', '设 \(f\) 在实轴上可导，且 \(f(x)=f(x+2)=f(x+\sqrt3)\)。用 Fourier 级数证明 \(f\) 为常数。', '\(f(x)\) 为常数。', '把 \(f\) 作为周期 2 的函数展开。平移 \(\sqrt3\) 后不变，而 \(\sqrt3/2\) 为无理数，故所有非零频率的 Fourier 系数均只能为零。可导性保证级数处处收敛到 \(f\)，所以只剩常数项。', '2016 年第八届全国大学生数学竞赛初赛（非数学类） 设 (f ) 在实轴上可导，且 (f(x)=f(x+2)=f(x+ 3) )。用 Fourier 级数证明 (f ) 为常数。 (f(x) ) 为常数。 把 (f ) 作为周期 2 的函数展开。平移 ( 3 ) 后不变，而 ( 3/2 ) 为无理数，故所有非零频率的 Fourier 系数均只能为零。可导性保证级数处处收敛到 (f )，所以只剩常数项。', '1', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, paper_id, question_no, sort_order, question_type, score, stem_md, answer_md, solution_md, search_text, source_page, status) VALUES ('99', '16', '1', '1', 'calculation', '30', '填空题，共 5 小题，每小题 6 分。

1. 求经过单叶双曲面 \(x^2/4+y^2/2-2z^2=1\) 与球面 \(x^2+y^2+z^2=4\) 的交线，且垂直于直线 \(x=0,3y+z=0\) 的平面。
2. 可微函数满足 \(f_x=-f\)、\(f(0,\pi/2)=1\)，且 \(\lim_{n\to\infty}[f(0,y+1/n)/f(0,y)]^n=e^{\cot y}\)。求 \(f(x,y)\)。
3. \(A\) 为 \(n\) 阶可逆反对称矩阵，\(b\) 为列向量，求 \(\operatorname{rank}\begin{pmatrix}A&b\\b^T&0\end{pmatrix}\)。
4. 求 \(\sum_{n=1}^{100}n^{-1/2}\) 的整数部分。
5. 曲线 \(y=x^3/3+2x\ (0\le x\le1)\) 绕直线 \(y=x/2\) 旋转，求旋转曲面面积。', '1. \(y-3z=0\)。 2. \(f=e^{-x}\sin y\)。 3. \(n\)。 4. \(18\)。
5. \(\displaystyle\frac53(2\sqrt2-1)\pi\)。', '1. 所求平面法向量取直线方向向量，代入交线上一点得方程。
2. 第一条件给出 \(f=e^{-x}C(y)\)，第二条件化为 \(C''/C=\cot y\)，再用初值。
3. Schur 补为 \(-b^TA^{-1}b=0\)，故秩等于 \(\operatorname{rank}A=n\)。
4. 用积分上下估计夹在 18 与 19 之间。
5. 用 \(dS=2\pi d\,ds\)，其中到轴距离 \(d=(x^3+2x)/\sqrt5\)，积分即得。', '2017 年第八届全国大学生数学竞赛决赛（非数学类） 填空题，共 5 小题，每小题 6 分。 1. 求经过单叶双曲面 (x 2/4+y 2/2-2z 2=1 ) 与球面 (x 2+y 2+z 2=4 ) 的交线，且垂直于直线 (x=0,3y+z=0 ) 的平面。 2. 可微函数满足 (f x=-f )、 (f(0, /2)=1 )，且 ( n [f(0,y+1/n)/f(0,y)] n=e y )。求 (f(x,y) )。 3. (A ) 为 (n ) 阶可逆反对称矩阵， (b ) 为列向量，求 ( rank pmatrix A&b T&0 pmatrix )。 4. 求 ( n=1 100 n -1/2 ) 的整数部分。 5. 曲线 (y=x 3/3+2x (0 x 1) ) 绕直线 (y=x/2 ) 旋转，求旋转曲面面积。 1. (y-3z=0 )。 2. (f=e -x y )。 3. (n )。 4. (18 )。 5. ( 53(2 2-1) )。 1. 所求平面法向量取直线方向向量，代入交线上一点得方程。 2. 第一条件给出 (f=e -x C(y) )，第二条件化为 (C''/C= y )，再用初值。 3. Schur 补为 (-b TA -1 b=0 )，故秩等于 ( rank A=n )。 4. 用积分上下估计夹在 18 与 19 之间。 5. 用 (dS=2 d ,ds )，其中到轴距离 (d=(x 3+2x)/ 5 )，积分即得。', '1', 'published') ON CONFLICT (id) DO NOTHING;